'use strict';

/* eslint-env jest */

const ImageRecords = require('../../computed/image-records.js');
const NetworkRequest = require('../../lib/network-request.js');

/**
 * @param {Partial<LH.Artifacts.NetworkRequest>=} partial
 * @return {LH.Artifacts.NetworkRequest}
 */
function mockRequest(partial = {}) {
  const request = new NetworkRequest();
  return Object.assign(request, partial);
}

/**
 * @param {Partial<LH.Artifacts.ImageElement>=} partial
 * @return {LH.Artifacts.ImageElement}
 */
function mockElement(partial = {}) {
  return {
    src: 'https://example.com/img.png',
    srcset: '',
    displayedWidth: 200,
    displayedHeight: 200,
    clientRect: {
      top: 50,
      bottom: 250,
      left: 50,
      right: 250,
    },
    attributeWidth: '',
    attributeHeight: '',
    naturalDimensions: undefined,
    cssEffectiveRules: undefined,
    computedStyles: {position: 'absolute', objectFit: '', imageRendering: ''},
    isCss: false,
    isPicture: false,
    isInShadowDOM: false,
    node: {
      lhId: '__nodeid__',
      devtoolsNodePath: '1,HTML,1,BODY,1,DIV,1,IMG',
      selector: 'body > div > img',
      nodeLabel: 'img',
      snippet: '<img src="https://example.com/img.png">',
      boundingRect: {
        top: 50,
        bottom: 250,
        left: 50,
        right: 250,
        width: 200,
        height: 200,
      },
    },
    ...partial,
  };
}

describe('.indexNetworkRecords', () => {
  it('maps image urls to network records', () => {
    const networkRecords = [
      mockRequest({
        mimeType: 'image/png',
        url: 'https://example.com/img.png',
        finished: true,
        statusCode: 200,
      }),
      mockRequest({
        mimeType: 'application/octect-stream',
        url: 'https://example.com/img.webp',
        finished: true,
        statusCode: 200,
      }),
      mockRequest({
        mimeType: 'application/octect-stream',
        url: 'https://example.com/img.avif',
        finished: true,
        statusCode: 200,
      }),
    ];

    const index = ImageRecords.indexNetworkRecords(networkRecords);

    expect(index).toEqual({
      'https://example.com/img.avif': mockRequest({
        finished: true,
        mimeType: 'application/octect-stream',
        statusCode: 200,
        url: 'https://example.com/img.avif',
      }),
      'https://example.com/img.png': mockRequest({
        finished: true,
        mimeType: 'image/png',
        statusCode: 200,
        url: 'https://example.com/img.png',
      }),
      'https://example.com/img.webp': mockRequest({
        finished: true,
        mimeType: 'application/octect-stream',
        statusCode: 200,
        url: 'https://example.com/img.webp',
      }),
    });
  });

  it('ignores bad status codes', () => {
    const networkRecords = [
      mockRequest({
        mimeType: 'image/png',
        url: 'https://example.com/img.png',
        finished: true,
        statusCode: 200,
      }),
      mockRequest({
        mimeType: 'application/octect-stream',
        url: 'https://example.com/img.webp',
        finished: false,
      }),
      mockRequest({
        mimeType: 'application/octect-stream',
        url: 'https://example.com/img.avif',
        finished: true,
        statusCode: 404,
      }),
    ];

    const index = ImageRecords.indexNetworkRecords(networkRecords);

    expect(index).toEqual({
      'https://example.com/img.png': mockRequest({
        finished: true,
        mimeType: 'image/png',
        statusCode: 200,
        url: 'https://example.com/img.png',
      }),
    });
  });
});

describe('compute_', () => {
  it('takes mime type from network record', async () => {
    const elements = await ImageRecords.compute_({
      ImageElements: [
        mockElement(),
      ],
      networkRecords: [
        mockRequest({
          mimeType: 'image/png',
          url: 'https://example.com/img.png',
          finished: true,
          statusCode: 200,
        }),
      ],
    });

    expect(elements).toEqual([mockElement({mimeType: 'image/png'})]);
  });

  it('keep element with no request', async () => {
    const elements = await ImageRecords.compute_({
      ImageElements: [
        mockElement({mimeType: 'image/png'}),
      ],
      networkRecords: [],
    });

    expect(elements).toEqual([mockElement({mimeType: 'image/png'})]);
  });

  it('keep guessed mime type of record has none', async () => {
    const elements = await ImageRecords.compute_({
      ImageElements: [
        mockElement({mimeType: 'image/png'}),
      ],
      networkRecords: [
        mockRequest({
          url: 'https://example.com/img.png',
          finished: true,
          statusCode: 200,
        }),
      ],
    });

    expect(elements).toEqual([mockElement({mimeType: 'image/png'})]);
  });
});

